import { readFileSync } from "node:fs";
import { defineConfig, type Plugin } from "vite";
import react from "@vitejs/plugin-react";

// VN-GEN-007: the licence, the NOTICE and the third-party notices for every bundled package (generated by
// scripts/check-deps.mjs) ship with the app.
const LEGAL_FILES = ["LICENSE", "NOTICE", "THIRD_PARTY_NOTICES.txt"];

function legalFiles(): Plugin {
  return {
    name: "vastness-legal-files",
    apply: "build",
    generateBundle() {
      for (const fileName of LEGAL_FILES) {
        const source = readFileSync(new URL(`./${fileName}`, import.meta.url), "utf8");
        this.emitFile({ type: "asset", fileName, source });
      }
    },
  };
}

// VN-GEN-001: a static build. `base` becomes /vastness/ for GitHub Pages in T-007.
export default defineConfig({
  base: "./",
  plugins: [react(), legalFiles()],
  worker: { format: "es" },
});
